package com.crm.crm.controller;
import com.crm.crm.entity.*; import com.crm.crm.service.*; import jakarta.validation.Valid; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.validation.BindingResult; import org.springframework.web.bind.annotation.*;
@Controller @RequestMapping("/tasks") public class TaskController {private final TaskService s;private final ClientService cs;public TaskController(TaskService s,ClientService cs){this.s=s;this.cs=cs;}private void opts(Model m){m.addAttribute("priorities",TaskPriority.values());m.addAttribute("statuses",TaskStatus.values());m.addAttribute("clients",cs.findAll());}@GetMapping public String list(Model m){m.addAttribute("tasks",s.findAll());return "tasks/list";}@GetMapping("/new") public String form(Model m){m.addAttribute("task",new Task());opts(m);return "tasks/form";}@GetMapping("/edit/{id}") public String edit(@PathVariable Long id,Model m){return s.findById(id).map(t->{m.addAttribute("task",t);opts(m);return "tasks/form";}).orElse("redirect:/tasks");}@PostMapping("/save") public String save(@Valid @ModelAttribute Task task,BindingResult br,@RequestParam(required=false) Long clientId,Model m){if(br.hasErrors()){opts(m);return "tasks/form";}task.setClient(clientId==null?null:cs.findById(clientId).orElse(null));s.save(task);return "redirect:/tasks";}@PostMapping("/delete/{id}") public String delete(@PathVariable Long id){s.delete(id);return "redirect:/tasks";}}
